  for (let i = 1; i < out.length; i++) if (out[i - 1] === '' && /^(?:\S+\s+){0,2}(?:её|его|их|она|он|оно|они|это|этот|эта|эти|там|тогда|it|its|this|these|they)(?=[\s,.;:])/i.test(out[i])) out[i] = '';
