  const files = listMd(KNOW);
  if (!files.length) return { missing: true };
  const assigned = new Map(); // rel → bundle file
  const skipped = files.filter(f => SCRIPT_ONLY.includes(f));
  for (const set of [CORE, EXTRA]) for (const b of set) for (const pat of b.parts) for (const rel of files) if (!assigned.has(rel) && !skipped.includes(rel) && matches(pat, rel)) assigned.set(rel, b.file);
