  for (const f of stray) assigned.set(f, EXTRA[EXTRA.length - 1].file);
  for (const [rel, file] of assigned) { KREF.set(rel, file); const base = rel.split('/').pop(); KREF.set(base, KREF.has(base) && KREF.get(base) !== file ? null : file); }
  for (const [k, v] of KREF) if (v == null) KREF.delete(k);
